export function labCart(g,color,x=0){const cart=new T.Group();cart.position.x=x;g.add(cart);box(cart,.85,.31,.64,color,0,.46,0);box(cart,.73,.065,.56,0xf8fbff,0,.66,0);box(cart,.18,.12,.5,C.metal,-.34,.43,0);box(cart,.18,.12,.5,C.metal,.34,.43,0);const wheels=[];for(const a of [-.27,.27])for(const z of [-.36,.36]){const w=new T.Group();w.position.set(a,.21,z);cart.add(w);const tire=mesh(w,new T.TorusGeometry(.11,.037,10,28),mat(0x344053,{roughness:.72,metalness:.02}));const hub=cylinder(w,.076,.09,C.metal);hub.rotation.x=Math.PI/2;const cap=cylinder(w,.024,.105,color);cap.rotation.x=Math.PI/2;for(let j=0;j<6;j++){const t=j*Math.PI/3;line(w,[V(.02*Math.cos(t),.02*Math.sin(t),z>0?.054:-.054),V(.068*Math.cos(t),.068*Math.sin(t),z>0?.054:-.054)],0xc6d5e5);}wheels.push(w);}for(const xx of [-.18,0,.18])box(cart,.065,.035,.012,C.dark,xx,.47,.327);cart.userData.roll=position=>wheels.forEach(w=>w.rotation.z=-position/(.148*cart.scale.x));return cart;}
export function lcd(g,pos,scale,o={}){if(o.labels===false)return null;const canvas=document.createElement('canvas');canvas.width=512;canvas.height=144;const ctx=canvas.getContext('2d');if(!ctx)return null;const texture=new T.CanvasTexture(canvas);texture.colorSpace=T.SRGBColorSpace;const sprite=new T.Sprite(new T.SpriteMaterial({map:texture,depthTest:true,transparent:true}));sprite.position.copy(pos);sprite.scale.set(scale,scale*.28125,1);sprite.userData.setText=t=>{if(sprite.userData.text===t)return;sprite.userData.text=t;ctx.clearRect(0,0,512,144);ctx.fillStyle='#143341';ctx.fillRect(0,0,512,144);ctx.fillStyle='#a2f3c6';ctx.font='600 62px monospace';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(t,256,75);texture.needsUpdate=true;};g.add(sprite);return sprite;}
export function digitalMeter(g,title,pos,o={},color=C.blue){const root=new T.Group();root.position.copy(pos);g.add(root);box(root,.94,.56,.56,0xf1f5fb,0,.28,0);box(root,.78,.34,.023,0x183949,0,.31,.291);for(const x of [-.34,.34])cylinder(root,.046,.024,C.metal,x,.10,.25).rotation.x=Math.PI/2;const l=lcd(root,V(0,.31,.322),.69,{...o,labels:true});if(l)l.material.depthTest=true;const name=label(root,title,V(0,.94,0),o);name?.scale.set(1.15,.24,1);const red=sphere(root,.055,C.orange,-.27,.1,.296),blue=sphere(root,.055,color,.27,.1,.296);return {root,positive:pos.clone().add(V(-.27,.1,.3)),negative:pos.clone().add(V(.27,.1,.3)),set:value=>setText(l,value)};}
export function powerSupply(g,pos,o){const root=new T.Group();root.position.copy(pos);g.add(root);box(root,1.15,.9,.86,0xf0f5fc,0,.5,0);box(root,1.03,.73,.025,0xdee8f4,0,.5,.443);box(root,.66,.24,.028,0x234054,-.1,.68,.461);const screen=lcd(root,V(-.1,.68,.49),.58,{...o,labels:true});if(screen)screen.material.depthTest=true;const knobs=[];for(const x of [-.30,.14]){const knob=new T.Group();knob.position.set(x,.37,.49);knob.userData.drag=x<0?'source-voltage':'source-voltage-fine';root.add(knob);const m=cylinder(knob,.09,.065,C.dark);m.rotation.x=Math.PI/2;line(knob,[V(0,0,.04),V(0,.062,.04)],0xe1ebf7);knobs.push(knob);}sphere(root,.029,C.green,.4,.72,.484);for(let j=0;j<5;j++)box(root,.045,.3,.019,0xadbecf,.27+j*.085,.35,-.435);const positive=pos.clone().add(V(-.29,.14,.47)),negative=pos.clone().add(V(.29,.14,.47));for(const [x,color]of [[-.29,C.orange],[.29,C.blue]]){const rim=cylinder(root,.058,.027,color,x,.14,.47);rim.rotation.x=Math.PI/2;cylinder(root,.025,.031,C.dark,x,.14,.485).rotation.x=Math.PI/2;}label(root,o.sourceTitle||'Nguồn DC',V(0,1.23,0),o)?.scale.set(1.3,.28,1);return {root,positive,negative,set:u=>{setText(screen,u.toFixed(1)+' V');knobs[0].rotation.z=-u/12*Math.PI*1.5;knobs[1].rotation.z=-(u%1)*Math.PI*1.5;}};}
export function cable(g,points,color=C.blue,r=.026){const curve=new T.CatmullRomCurve3(points);const tube=mesh(g,new T.TubeGeometry(curve,48,r,8,false),mat(color,{roughness:.42,metalness:.05}));return tube;}
export function premiumOhm(g,s,d,o){platform(g,7.8,5.2);const source=powerSupply(g,V(-2.5,.06,-.35),o),ammeter=digitalMeter(g,'Ampe kế',V(2.1,.07,.25),o),voltmeter=digitalMeter(g,'Vôn kế',V(0,.07,1.05),o,C.purple),resistor=cylinder(g,.17,1.35,0xd7b082,.1,.65,-1.35);resistor.rotation.z=Math.PI/2;for(const [x,color]of [[-.35,0x715347],[-.11,0x455a91],[.14,0x714376],[.46,0xc0a95e]]){const ring=mesh(g,new T.TorusGeometry(.174,.031,8,32),mat(color),x+.1,.65,-1.35);ring.rotation.y=Math.PI/2;}const left=V(-.64,.65,-1.35),right=V(.84,.65,-1.35);for(const p of [left,right]){cylinder(g,.09,.45,C.metal,p.x,.285,p.z);cylinder(g,.22,.04,0xc9d6e6,p.x,.08,p.z);}line(g,[left,right],C.metal);const paths=[[source.positive,V(-2.8,.2,-1.7),V(-.9,.25,-1.65),left],[right,V(2.7,.22,-1.8),V(2.8,.18,-.4),ammeter.positive],[ammeter.negative,V(2.8,.16,1.75),V(-2.7,.15,1.75),source.negative]];paths.forEach((p,j)=>cable(g,p,j===0?C.orange:C.blue));cable(g,[left,V(-1.25,.18,0),voltmeter.positive],C.purple,.022);cable(g,[right,V(1.10,.18,.5),voltmeter.negative],C.purple,.022);const rLabel=label(g,'',V(.1,1.25,-1.35),o);rLabel?.scale.set(1.7,.32,1);const curves=paths.map(p=>new T.CatmullRomCurve3(p)),lengths=curves.map(c=>c.getLength()),total=lengths.reduce((a,b)=>a+b),dots=new T.InstancedMesh(new T.SphereGeometry(.045,10,8),mat(0xffc26d,{emissive:0xffb347,emissiveIntensity:.45}),20),dummy=new T.Object3D();g.add(dots);return(s,d)=>{source.set(s.u);ammeter.set(d.i.toFixed(3)+' A');voltmeter.set(s.u.toFixed(1)+' V');setText(rLabel,`R = ${s.r.toFixed(0)} Ω`);resistor.material.emissive.setHex(C.orange);resistor.material.emissiveIntensity=Math.min(.3,d.p/150);dots.visible=d.i>0;for(let j=0;j<20;j++){let dist=(((s.t||0)*(.8+d.i*.8)+j*total/20)%total),index=0;while(index<2&&dist>lengths[index])dist-=lengths[index++];dummy.position.copy(curves[index].getPointAt(dist/lengths[index]));dummy.updateMatrix();dots.setMatrixAt(j,dummy.matrix);}dots.instanceMatrix.needsUpdate=true;};}
export function upgradeModel(model,id,s,d,o){const lights=[];model.group.traverse(obj=>{if(obj.userData.lightPath)lights.push(obj);});const movers=lights.map(path=>{const dots=new T.InstancedMesh(new T.SphereGeometry(.042,10,8),mat(path.material.color,{emissive:path.material.color,emissiveIntensity:.7}),8);model.group.add(dots);return {path,dots}}),dummy=new T.Object3D(),original=model.update;
model.update=(s,d,c={})=>{original(s,d,c);model.group.traverse(obj=>{if(obj.userData.roll)obj.userData.roll(obj.position.x);});for(const {path,dots}of movers){dots.visible=path.visible&&c.switches?.light!==false;dots.material.color.copy(path.material.color);dots.material.emissive.copy(path.material.color);const attr=path.geometry.attributes.position,points=Array.from({length:attr.count},(_,i)=>V(attr.getX(i),attr.getY(i),attr.getZ(i))),lens=points.slice(1).map((p,i)=>p.distanceTo(points[i])),total=lens.reduce((a,b)=>a+b,0);for(let j=0;j<8;j++){let x=(((s.t||0)*.8+j*total/8)%Math.max(.001,total)),k=0;while(k<lens.length-1&&x>lens[k])x-=lens[k++];dummy.position.copy(points[k]).lerp(points[k+1],lens[k]>0?x/lens[k]:0);dummy.updateMatrix();dots.setMatrixAt(j,dummy.matrix);}dots.instanceMatrix.needsUpdate=true;}};model.update(s,d,o.config||{});return model;}
